<style>
.pm-page{font-family:Inter,sans-serif;color:#25313C}.pm-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:22px}.pm-title{font-size:23px;font-weight:700;color:#123B5D;margin:0}.pm-sub{font-size:13px;color:#64748B;margin:6px 0 0}.pm-actions{display:flex;gap:9px;flex-wrap:wrap}.pm-btn{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 16px;border-radius:9px;border:1px solid #CBD5E1;background:#fff;color:#334155;font-size:13px;font-weight:600;text-decoration:none;cursor:pointer}.pm-btn.primary{background:#123B5D;border-color:#123B5D;color:#fff}.pm-panel{background:#fff;border:1px solid #CBD5E1;border-radius:15px;padding:18px;margin-bottom:16px}.pm-panel h3{font-size:15px;color:#123B5D;margin:0 0 14px;font-weight:700}.pm-toolbar{display:flex;align-items:end;gap:12px;flex-wrap:wrap}.pm-field label{display:block;font-size:12px;font-weight:650;color:#334155;margin-bottom:6px}.pm-field select{min-width:240px;border:1px solid #CBD5E1;border-radius:9px;padding:10px 12px;font:13px Inter,sans-serif;background:#fff}.pm-alert{padding:11px 13px;border-radius:9px;background:#F0FDF4;color:#166534;margin-bottom:14px;font-size:13px}.pm-error{background:#FEF2F2;color:#991B1B}.pm-group{border:1px solid #E2E8F0;border-radius:12px;margin-bottom:13px;overflow:hidden}.pm-group-head{display:flex;justify-content:space-between;align-items:center;padding:13px 15px;background:#F8FAFC;border-bottom:1px solid #E2E8F0}.pm-group-head strong{font-size:13px;color:#123B5D}.pm-group-head span{font-size:11px;color:#64748B}.pm-perm{display:grid;grid-template-columns:minmax(180px,1.1fr) minmax(160px,1fr) minmax(90px,.5fr);gap:12px;align-items:center;padding:12px 15px;border-bottom:1px solid #F1F5F9}.pm-perm:last-child{border-bottom:0}.pm-name{font-size:12px;font-weight:650;color:#334155}.pm-code{font-size:11px;color:#64748B;margin-top:3px}.pm-desc{font-size:12px;color:#64748B}.pm-toggle{display:flex;align-items:center;gap:8px;font-size:12px;color:#334155}.pm-toggle input{width:16px;height:16px;accent-color:#176B87}.pm-count{font-size:12px;color:#64748B}.pm-sticky{position:sticky;bottom:12px;display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 15px;background:#fff;border:1px solid #CBD5E1;border-radius:12px;box-shadow:0 5px 20px #0f172a12}.pm-compare{width:100%;border-collapse:collapse}.pm-compare th,.pm-compare td{padding:11px;border-bottom:1px solid #E2E8F0;text-align:left;font-size:12px}.pm-compare th{background:#F8FAFC;color:#64748B;font-size:11px}.pm-yes{color:#15803D;font-weight:700}.pm-no{color:#94A3B8}.pm-empty{text-align:center;padding:25px;color:#64748B;font-size:13px}@media(max-width:760px){.pm-head{display:block}.pm-actions{margin-top:13px}.pm-perm{grid-template-columns:1fr 1fr}.pm-desc{grid-column:1/-1}.pm-field select{min-width:0;width:100%}}
</style>